package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Records outside a transaction are appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/**
 * The signed-in user, as the screen sends it on every change in the {@link #HEADER} header,
 * URI-encoded so any typed name fits in a header.
 */
public final class SignedIn {

    public static final String HEADER = "X-User";

    private SignedIn() {
    }

    /** The user's name from the header's value. */
    public static String name(String header) {
        return URLDecoder.decode(header.replace("+", "%2B"), StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * What the screen is told about a grade's rate; the percent with two decimals, and the date it
     * applies from (null: from the beginning of time).
     */
    public record RateView(String grade, String pct, LocalDate from) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().toPlainString(), rate.getFromDate());
        }
    }

    /**
     * A rate as entered on the form: a percent of 0.00 or more with up to two decimals, and the date
     * it applies from (none: from the beginning of time).
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from) {
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    /** The sheet's rates by grade, each grade's by from-date; a grade with no rate is not listed. */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    /** Set the rate for a grade from a date, replacing any it had from that date. */
    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RateForm form) {
        return RateView.of(service.set(sheetId, SignedIn.name(user), grade, form.from(),
                new BigDecimal(form.pct())));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A rate for a grade (A, B or C) on a sheet: a percent with two decimals, applying from its
 * from-date, or from the beginning of time when it has none.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate fromDate;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    /** The date the rate applies from; null when it applies from the beginning of time. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** Whether the rate applies to a claim on a date: it has no from-date, or one on or before the date. */
    public boolean appliesOn(LocalDate date) {
        return fromDate == null || !fromDate.isAfter(date);
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates by grade, each grade's from the earliest from-date (none first). */
    List<Rate> findBySheetIdOrderByGradeAscFromDateAscIdAsc(String sheetId);

    /** A grade's rates on the sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate with this from-date; a null from-date finds the one with none. */
    Optional<Rate> findBySheetIdAndGradeAndFromDate(String sheetId, String grade, LocalDate fromDate);

    /**
     * The rate a claim on a date uses for a grade: of the grade's rates with no from-date or one on
     * or before the date, the one with the latest; empty when the date is before every rate.
     */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates for the grades on a sheet: listed and set. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Rollups rollups, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's rates by grade. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
    }

    /**
     * Set the rate for a grade from a date (null: from the beginning of time), replacing any the
     * grade had from that same date.
     */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, LocalDate from, BigDecimal pct) {
        sheets.load(sheetId);
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal percent = pct.setScale(2, RoundingMode.UNNECESSARY);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from)
                .orElseGet(() -> new Rate(sheetId, grade, from, percent));
        rate.setPct(percent);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : ""));
        rollups.audit(sheetId, user, before);
        return saved;
    }
}
-- The rate for a grade on a sheet: a percent with two decimals (0.00 or more). A sheet holds at
-- most one rate per grade; a grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)   NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)       NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A rate may carry a from-date: it applies to claims dated on or after it, until the next rate's
-- from-date for the same grade. A rate with no from-date applies from the beginning of time. A
-- sheet holds at most one rate per grade and from-date (one with none per grade, kept by the app).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- A rate may carry a from-date: it applies to claims dated on or after it, until the next rate's
-- from-date for the same grade. A rate with no from-date applies from the beginning of time. A
-- sheet holds at most one rate per grade and from-date (one with none per grade, kept by the app).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- Who opened a claim: the signed-in user's name, set when the claim is opened. Null while DRAFT, and
-- for a claim voided before it was opened. That user cannot settle the claim (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
-- The version of a person: raised on every save, so an editor that loaded an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- A person's statements: how many have been taken, and the due-total and date (the sheet's today) of
-- the last one. The last due-total is null with no statement, or when it was n/a.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN statement_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: stated, with the due figure it had then (null when
-- it was n/a). A claim that did not count at the statement is left unbound, its due live again.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
-- A period on a sheet: a name, unique on the sheet ignoring case and surrounding spaces (name_key is
-- the trimmed name lower-cased), and a from and to date, both inclusive. No two periods on a sheet
-- overlap (kept by the app). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
